checkShop().catch(console.error);
"

"import fs from 'fs';

const html = fs.readFileSync('scratch/babimate_pdp.html', 'utf8');

// search for price patterns or json in HTML
const matchMeta = html.match(/<meta property="og:price:amount" content="([^"]+)">/);
const matchCurr = html.match(/<meta property="og:price:currency" content="([^"]+)">/);
console.log('OG Price:', matchMeta ? matchMeta[1] : null, matchCurr ? matchCurr[1] : null);

// Search for original price in USD
const scripts = html.match(/<script[^>]*>([\s\S]*?)<\/script>/gi) || [];
for (const s of scripts) {
  if (s.includes('price') && s.includes('USD')) {
    console.log('Found script with USD:', s.substring(0, 300));
  }
}

// Let's also check if we can fetch babimate with currency header or ?currency=USD
async function testUSD() {
  const res = await fetch('https://babimate.com/products/babiguard-1.json?currency=USD', {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Cookie': 'cart_currency=USD; localization=US'
    }
  });
  const data = await res.json();
  console.log('With USD cookie/param: Variant 0 price:', data.product?.variants[0]?.price, 'Compare:', data.product?.variants[0]?.compare_at_price);

  const resHtml = await fetch('https://babimate.com/products/babiguard-1?currency=USD', {
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Cookie': 'cart_currency=USD; localization=US'
    }
  });
  const h = await resHtml.text();
  const m = h.match(/\$\d+(\.\d{2})?/g);
  console.log('Prices found with $ sign in HTML:', [...new Set(m)]);
}

testUSD().catch(console.error);
"

"import fs from 'fs';

const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = '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';
const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const THEME_ID = '187597717689'; // Live theme

async function getThemeAsset(key) {
  const tokenRes = await fetch('https://' + SHOP_DOMAIN + '/admin/oauth/access_token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const { access_token } = await tokenRes.json();
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${THEME_ID}/assets.json?asset[key]=${encodeURIComponent(key)}`, {
    headers: { 'X-Shopify-Access-Token': access_token }
  });
  const data = await res.json();
  return data.asset?.value;
}

async function inspectTemplates() {
  const defaultProd = await getThemeAsset('templates/product.json');
  console.log('--- templates/product.json ---');
  if (defaultProd) {
    fs.writeFileSync('scratch/live_product.json', defaultProd);
    const parsed = JSON.parse(defaultProd);
    console.log('Sections order:', parsed.order);
    console.log('Section types:', Object.entries(parsed.sections).map(([k, v]) => `${k} -> ${v.type}`));
  }

  // Also check product.zavelyn.json or others
  const zavelynProd = await getThemeAsset('templates/product.zavelyn.json');
  if (zavelynProd) {
    fs.writeFileSync('scratch/live_product.zavelyn.json', zavelynProd);
    const parsed = JSON.parse(zavelynProd);
    console.log('\n--- templates/product.zavelyn.json ---');
    console.log('Sections order:', parsed.order);
    console.log('Section types:', Object.entries(parsed.sections).map(([k, v]) => `${k} -> ${v.type}`));
  }
}

inspectTemplates().catch(console.error);
"

