async function uploadAsset(token, key, content) {
  console.log(`Uploading asset: ${key} (${content.length} bytes)...`);
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${THEME_ID}/assets.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({
      asset: {
        key: key,
        value: content
      }
    })
  });
  const data = await res.json();
  if (data.asset) {
    console.log(`✔ Successfully uploaded: ${data.asset.key}`);
    return true;
  } else {
    console.error(`❌ Failed to upload ${key}:`, JSON.stringify(data));
    return false;
  }
}

async function main() {
  const token = await getAccessToken();

  const sectionContent = fs.readFileSync('sections/zavelyn-babiguard-body.liquid', 'utf8');
