"import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || "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";

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials'
    })
  });
  const data = await res.json();
  return data.access_token;
}

async function activateProduct() {
  const token = await getAccessToken();
  const productId = '15424286589113';

  const updateBody = {
    product: {
      id: productId,
      status: 'active',
      template_suffix: 'rehab-glove',
      title: 'Zavelyn™ Robotic Stroke & Hand Rehabilitation Glove'
    }
  };

  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/products/${productId}.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify(updateBody)
  });

  const data = await res.json();
  console.log('Update result:', data.product ? {
    id: data.product.id,
    title: data.product.title,
    handle: data.product.handle,
    status: data.product.status,
    template_suffix: data.product.template_suffix
  } : data);
}

activateProduct().catch(console.error);
"

