"import fs from 'fs';

const content = fs.readFileSync('backups/live_theme_186607567033_1793118315494/sections/offer-zavelyn.liquid', 'utf8');

function extractSection(secClass) {
  const marker = `class="offer-sec ${secClass}"`;
  const idx = content.indexOf(marker);
  if (idx === -1) return null;
  const endIdx = content.indexOf('</section>', idx);
  return content.slice(idx, endIdx + 10);
}

const sections = [
  'offer-sec--iwt-story',
  'offer-sec--train',
  'offer-sec--features',
  'offer-sec--howto',
  'offer-sec--benefits',
  'offer-sec--realistic',
  'offer-sec--stats',
  'offer-sec--compare',
  'offer-sec--timeline',
  'offer-sec--reviews',
  'offer-sec--faq'
];

sections.forEach(s => {
  const html = extractSection(s);
  console.log(`\n=== SECTION: ${s} ===`);
  if (html) {
    const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    console.log(text.slice(0, 250) + '...');
  } else {
    console.log('NOT FOUND');
  }
});
"

