123:     if (fs.existsSync(localPath)) {
124:       if (isText) {
125:         assetData = { key, value: fs.readFileSync(localPath, 'utf8') };
126:       } else {
127:         assetData = { key, attachment: fs.readFileSync(localPath).toString('base64') };
128:       }
129:     } else {
130:       assetData = await getAsset(token, LIVE_THEME_ID, key);
131:       if (assetData) {
132:         if (assetData.value !== undefined) {
133:           fs.writeFileSync(localPath, assetData.value, 'utf8');
134:         } else if (assetData.attachment !== undefined) {
135:           fs.writeFileSync(localPath, Buffer.from(assetData.attachment, 'base64'));
136:         }
137:         downloadedCount++;
138:       }
139:       await new Promise(r => setTimeout(r, 100));
140:     }
141: 
142:     // Step B: upload to draft theme if missing
143:     if (!existingInDraft.has(key)) {
144:       try {
145:         await putAsset(token, DRAFT_THEME_ID, assetData);
146:         uploadedCount++;
147:         existingInDraft.add(key);
148:       } catch (err) {
149:         console.error(`Error uploading [Stage ${stage}] ${key}:`, err.message);
150:       }
151:       await new Promise(r => setTimeout(r, 120));
152:     } else {
153:       skippedCount++;
154:     }
155: 
156:     if ((i + 1) % 20 === 0 || i === sortedAssets.length - 1 || stage < 8) {
157:       console.log(`[Stage ${stage}] Processed ${i + 1}/${sortedAssets.length} (${key}) | Uploaded: ${uploadedCount} | Skipped: ${skippedCount}`);
158:     }
159:   }
160: 
161:   console.log(`\n🎉 Theme sync complete!`);
162:   console.log(`Draft theme ID: ${DRAFT_THEME_ID}`);
163:   console.log(`Backup location: ${BACKUP_DIR}`);
164: }
