"import fs from 'fs';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';
const DRAFT_THEME_ID = 189127983289;

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function main() {
  const token = await getAccessToken();
  const draftRes = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${DRAFT_THEME_ID}/assets.json`, {
    headers: { 'X-Shopify-Access-Token': token }
  });
  const draftData = await draftRes.json();
  const draftAssets = new Set((draftData.assets || []).map(a => a.key));
  console.log(`Draft theme asset count: ${draftAssets.size}`);

  const liveList = JSON.parse(fs.readFileSync('scratch/live_assets_list.json', 'utf8'));
  const missingCodeAssets = liveList.filter(a => {
    const isCode = a.key.startsWith('locales/') || a.key.startsWith('config/') || a.key.startsWith('snippets/') || a.key.startsWith('sections/') || a.key.startsWith('layout/') || a.key.startsWith('templates/');
    return isCode && !draftAssets.has(a.key);
  });

  console.log(`Missing code assets on draft theme: ${missingCodeAssets.length}`);
  for (const a of missingCodeAssets) {
    console.log(` - ${a.key}`);
  }
}

main().catch(console.error);
"

"import fs from 'fs';
import path from 'path';

const SHOP_DOMAIN = 'dsdujr-vn.myshopify.com';
const CLIENT_ID = '172e9e29abd0fe12f671d8441479c7c2';
const CLIENT_SECRET = process.env.SHOPIFY_API_SECRET || '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';
const DRAFT_THEME_ID = 189127983289;
const BACKUP_DIR = path.resolve('backup_live_187597717689');

async function getAccessToken() {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/oauth/access_token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, grant_type: 'client_credentials' })
  });
  const data = await res.json();
  return data.access_token;
}

async function putAsset(token, themeId, key, value) {
  const res = await fetch(`https://${SHOP_DOMAIN}/admin/api/2024-01/themes/${themeId}/assets.json`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': token
    },
    body: JSON.stringify({ asset: { key, value } })
  });
  if (!res.ok) {
    const text = await res.text();
    console.error(`Failed ${key}: ${res.status} ${text}`);
    return false;
  }
  console.log(`Success: ${key}`);
  return true;
}

async function main() {
  const token = await getAccessToken();
  const keys = ['sections/header-group.json', 'sections/footer-group.json'];
  for (const k of keys) {
    const val = fs.readFileSync(path.join(BACKUP_DIR, k), 'utf8');
    await putAsset(token, DRAFT_THEME_ID, k, val);
  }
}

main().catch(console.error);
"

