"import fs from 'fs';

class CookieJar {
  constructor() { this.cookies = new Map(); }
  setFromHeaders(headers) {
    let raw = [];
    if (typeof headers.getSetCookie === 'function') raw = headers.getSetCookie();
    else { const h = headers.get('set-cookie'); if (h) raw = [h]; }
    for (const cookieStr of raw) {
      const parts = cookieStr.split(';');
      const [nameVal] = parts;
      const eqIdx = nameVal.indexOf('=');
      if (eqIdx !== -1) {
        this.cookies.set(nameVal.slice(0, eqIdx).trim(), nameVal.slice(eqIdx + 1).trim());
      }
    }
  }
  getCookieHeader() {
    return Array.from(this.cookies.entries()).map(([k, v]) => `${k}=${v}`).join('; ');
  }
}

async function fetchWithCookies(url, jar, options = {}) {
  const headers = { ...(options.headers || {}) };
  const cookieHeader = jar.getCookieHeader();
  if (cookieHeader) headers['Cookie'] = cookieHeader;
  const res = await fetch(url, { ...options, headers, redirect: 'manual' });
  jar.setFromHeaders(res.headers);
  if (res.status >= 300 && res.status < 400 && res.headers.get('location')) {
    const loc = new URL(res.headers.get('location'), url).toString();
    return fetchWithCookies(loc, jar, options);
  }
  return res;
}

async function main() {
  const jar = new CookieJar();
  const THEME_ID = '189127983289';
  await fetchWithCookies('https://tryzavelyn.com/?preview_theme_id=' + THEME_ID, jar);

  const colUrl = 'https://tryzavelyn.com/collections/zvhc-all';
  const res = await fetchWithCookies(colUrl, jar);
  console.log('Collection /collections/zvhc-all status:', res.status);
  const html = await res.text();
  console.log('Collection HTML length:', html.length);
  console.log('has zvhc-header:', html.includes('zvhc-header'));
}

main().catch(console.error);
