  'layout/theme.liquid'
];

let allValid = true;

for (const f of filesToValidate) {
  if (!fs.existsSync(f)) {
    console.error(`❌ File not found: ${f}`);
    allValid = false;
    continue;
  }
  const content = fs.readFileSync(f, 'utf8');

  // If JSON, validate parse
  if (f.endsWith('.json')) {
    try {
      JSON.parse(content);
      console.log(`✅ ${f}: Valid JSON`);
    } catch (e) {
      console.error(`❌ ${f}: Invalid JSON - ${e.message}`);
      allValid = false;
    }
    continue;
  }

  // If Liquid, extract {% schema %} if present and validate
  const schemaMatch = content.match(/\{%\s*schema\s*%\}([\s\S]*?)\{%\s*endschema\s*%\}/);
  if (schemaMatch) {
    try {
      const parsedSchema = JSON.parse(schemaMatch[1]);
      if (parsedSchema.name && parsedSchema.name.length > 25) {
        console.error(`❌ ${f}: Schema name too long (>25 chars): "${parsedSchema.name}" (${parsedSchema.name.length})`);
        allValid = false;
      } else {
        console.log(`✅ ${f}: Schema valid (name: "${parsedSchema.name}", length: ${parsedSchema.name?.length || 0})`);
      }
    } catch (e) {
      console.error(`❌ ${f}: Schema JSON parse error - ${e.message}`);
      allValid = false;
    }
  } else {
    console.log(`✅ ${f}: Liquid file verified (no schema block required)`);
  }
}

if (allValid) {
  console.log('\n🎉 ALL VALIDATED ASSETS PASSED SYNTAX & SCHEMA CHECKS!');
} else {
  process.exit(1);
}
